-- Notifications: generated by triggers on kudos events, readable and markable by their owner only.
begin;
create extension if not exists pgtap with schema extensions;
select plan(24);

insert into auth.users (id, email, aud, role, raw_user_meta_data) values
  ('a1111111-1111-4111-8111-111111111111', 'a@sun.test', 'authenticated', 'authenticated',
   '{"full_name":"Alice Nguyen"}'),
  ('b2222222-2222-4222-8222-222222222222', 'b@sun.test', 'authenticated', 'authenticated',
   '{"full_name":"Bob Tran"}'),
  ('c3333333-3333-4333-8333-333333333333', 'c@sun.test', 'authenticated', 'authenticated',
   '{"full_name":"Carol Le"}');
update public.profiles set full_name = 'Alice Nguyen' where id = 'a1111111-1111-4111-8111-111111111111';
update public.profiles set full_name = 'Bob Tran' where id = 'b2222222-2222-4222-8222-222222222222';
update public.profiles set full_name = 'Carol Le' where id = 'c3333333-3333-4333-8333-333333333333';

-- Alice -> Bob (named), Carol -> Bob (anonymous, nickname "Mèo"), set up as owner.
insert into public.kudos (id, sender_id, recipient_id, content) values
  ('d4444444-4444-4444-8444-444444444444', 'a1111111-1111-4111-8111-111111111111',
   'b2222222-2222-4222-8222-222222222222', 'Thanks Bob');
insert into public.kudos (id, sender_id, recipient_id, content, is_anonymous, anonymous_name) values
  ('e5555555-5555-4555-8555-555555555555', 'c3333333-3333-4333-8333-333333333333',
   'b2222222-2222-4222-8222-222222222222', 'Secret thanks', true, 'Mèo');
insert into public.secret_boxes (id, owner_id) values
  ('f6666666-6666-4666-8666-666666666666', 'c3333333-3333-4333-8333-333333333333');

-- Bob (recipient) sees his two kudos_received notifications.
set local role authenticated;
set local request.jwt.claims = '{"sub":"b2222222-2222-4222-8222-222222222222","role":"authenticated"}';

select is(
  (select count(*) from public.notifications where type = 'kudos_received')::int, 2,
  'recipient gets kudos_received for each kudos'
);
select is(
  (select payload->>'senderName' from public.notifications
    where payload->>'kudosId' = 'd4444444-4444-4444-8444-444444444444'),
  'Alice Nguyen', 'named kudos stores the sender name'
);
select results_eq(
  $$select payload->>'senderName', (payload->>'isAnonymous')::boolean from public.notifications
    where payload->>'kudosId' = 'e5555555-5555-4555-8555-555555555555'$$,
  $$values ('Mèo'::text, true)$$,
  'anonymous kudos stores only the nickname'
);
select is(
  (select count(*) from public.notifications
    where payload::text like '%c3333333-3333-4333-8333-333333333333%'
       or payload::text like '%Carol%')::int,
  0, 'anonymous sender id and name never reach the notification'
);

-- Bob likes Alice's kudos -> Alice gets heart_received.
insert into public.kudos_likes (kudos_id) values ('d4444444-4444-4444-8444-444444444444');
select is(
  (select count(*) from public.notifications)::int, 2,
  'liker does not get a notification for their own like'
);

select throws_ok(
  $$insert into public.notifications (recipient_id, type) values
    ('b2222222-2222-4222-8222-222222222222', 'kudos_received')$$,
  '42501', null, 'client cannot insert notifications'
);
select throws_ok(
  $$update public.notifications set is_read = true$$,
  '42501', null, 'client cannot update notifications directly'
);
select throws_ok(
  $$delete from public.notifications$$, '42501', null, 'client cannot delete notifications'
);

select is(public.mark_all_notifications_read(), 2, 'mark all read returns the updated count');
select is(public.mark_all_notifications_read(), 0, 'mark all read is idempotent');
select is(
  (select count(*) from public.notifications where not is_read)::int, 0,
  'all of Bob''s notifications are read'
);

-- Bob unlikes and likes again: still one heart notification for Alice.
delete from public.kudos_likes where kudos_id = 'd4444444-4444-4444-8444-444444444444';
insert into public.kudos_likes (kudos_id) values ('d4444444-4444-4444-8444-444444444444');

-- Alice: sender of the liked kudos.
set local request.jwt.claims = '{"sub":"a1111111-1111-4111-8111-111111111111","role":"authenticated"}';
select results_eq(
  $$select type::text, payload->>'actorName', payload->>'actorId' from public.notifications$$,
  $$values ('heart_received'::text, 'Bob Tran'::text, 'b2222222-2222-4222-8222-222222222222'::text)$$,
  'kudos sender gets exactly one heart_received per liker'
);
select is(
  (select count(*) from public.notifications
    where recipient_id <> 'a1111111-1111-4111-8111-111111111111')::int,
  0, 'a user sees only their own notifications'
);

-- Alice cannot mark Bob's notifications read; she can mark her own.
reset role;
update public.notifications set is_read = false
  where recipient_id = 'b2222222-2222-4222-8222-222222222222';
create temp table bob_note on commit drop as
  select id from public.notifications
  where recipient_id = 'b2222222-2222-4222-8222-222222222222' limit 1;
grant select on bob_note to authenticated;
set local role authenticated;
select is(
  public.mark_notification_read((select id from bob_note)),
  false, 'cannot mark another user''s notification read'
);
reset role;
select is(
  (select count(*) from public.notifications
    where recipient_id = 'b2222222-2222-4222-8222-222222222222' and is_read)::int,
  0, 'other user''s notification stays unread'
);
set local role authenticated;
select is(
  public.mark_notification_read((select id from public.notifications limit 1)),
  true, 'owner marks one notification read'
);
select is(
  (select is_read from public.notifications limit 1), true, 'the notification is now read'
);

-- Carol: secret box owner.
set local request.jwt.claims = '{"sub":"c3333333-3333-4333-8333-333333333333","role":"authenticated"}';
select results_eq(
  $$select type::text, payload->>'boxId' from public.notifications$$,
  $$values ('secret_box_available'::text, 'f6666666-6666-4666-8666-666666666666'::text)$$,
  'box owner gets secret_box_available'
);

-- anon: nothing.
set local role anon;
set local request.jwt.claims = '{"role":"anon"}';
select throws_ok(
  $$select count(*) from public.notifications$$, '42501', null, 'anon cannot read notifications'
);
select throws_ok(
  $$select public.mark_all_notifications_read()$$, '42501', null, 'anon cannot mark all read'
);
select throws_ok(
  $$select public.mark_notification_read(gen_random_uuid())$$, '42501', null,
  'anon cannot mark read'
);

reset role;
select ok(
  exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'notifications'
  ),
  'notifications are published to realtime'
);
select ok(
  not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and tablename = 'notifications'
      and 'payload' = any (attnames)
  ),
  'realtime publication leaves the payload out'
);
select is(
  public.hearts_received_by(public.heart_recipient_of('d4444444-4444-4444-8444-444444444444')),
  (select count(*) from public.notifications n
    where n.type = 'heart_received'
      and n.recipient_id = public.heart_recipient_of('d4444444-4444-4444-8444-444444444444'))::bigint,
  'hearts_received_by and heart_received notifications follow the same recipient rule'
);

select * from finish();
rollback;
